using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Text;
using System.Xml;
using AGS.Types;
using NUnit.Framework;

namespace AGS.Editor.Build
{
    /// <summary>
    /// The editor makes the generated script headers itself, for autocomplete, go-to-definition and
    /// the plugin API: _AutoGenerated.ash (Tasks.RegenerateScriptHeader) and _GlobalVariables.ash
    /// (Tasks.MakeGlobalVariablesHeader). agsbuild compiles the scripts with the ones that agfexport
    /// makes. These tests compare the two, line by line, so that they cannot drift apart.
    ///
    /// agfexport is taken from the build tree next to the tests' (Solutions/.build/x86/Release for
    /// Solutions/.test/x86/Release), or from the folder in AGS_TOOLS_DIR. The project is the folder
    /// (or Game.agf) in AGS_TEST_PROJECT, such as the auto-test game of the test games repository.
    /// Without either, the tests are ignored. The project is only read.
    /// </summary>
    [TestFixture]
    [Timeout(60000)]
    public class AgfexportHeaderTests
    {
        private const string ToolFileName = "agfexport.exe";
        private const string ToolsVariable = "AGS_TOOLS_DIR";
        private const string ProjectVariable = "AGS_TEST_PROJECT";

        private string _tool;
        private string _project;
        private string _dir;

        [SetUp]
        public void SetUp()
        {
            _tool = FindTool();
            if (_tool == null)
            {
                Assert.Ignore(ToolFileName + " is neither in " + DefaultToolsDir() + " nor in " + ToolsVariable +
                              ": build Solutions/Tools.sln, or set " + ToolsVariable + ".");
            }
            _project = FindProject();
            if (_project == null)
            {
                Assert.Ignore("Set " + ProjectVariable + " to a game project, such as the auto-test game of the " +
                              "test games repository.");
            }
            _dir = Path.Combine(Path.GetTempPath(), "AGS.Editor.Tests", "agfexport " + Guid.NewGuid().ToString("N"));
            Directory.CreateDirectory(_dir);
        }

        [TearDown]
        public void TearDown()
        {
            // the schema is shared by all the games of the process
            InteractionSchema.Instance.Events = new InteractionEvent[0];
            if (_dir == null)
            {
                return;
            }
            try
            {
                Directory.Delete(_dir, true);
            }
            catch (IOException ex)
            {
                TestContext.WriteLine("Cannot delete " + _dir + ": " + ex.Message);
            }
        }

        [Test]
        public void AutoGeneratedHeader_IsAgfexportAutoash()
        {
            Game game = LoadGame(_project);
            string header = Path.Combine(_dir, "_AutoGenerated.ash");

            RunTool("autoash", _project, header);

            string text = File.ReadAllText(header);
            Assert.That(text, Does.Contain("enum CursorMode"), "agfexport's header");
            AssertSameLines(text, new Tasks().RegenerateScriptHeader(game, null).Text);
        }

        [Test]
        public void GlobalVariablesHeader_IsAgfexportGlvar()
        {
            Game game = LoadGame(_project);
            string header = Path.Combine(_dir, "_GlobalVariables.ash");
            string body = Path.Combine(_dir, "_GlobalVariables.asc");

            RunTool("glvar", _project, header, body);

            AssertSameLines(File.ReadAllText(header), Tasks.MakeGlobalVariablesHeader(game.GlobalVariables.ToList()));
        }

        // Loads Game.agf into a Game, as the editor does when it opens a project in the current format
        private static Game LoadGame(string path)
        {
            var doc = new XmlDocument();
            doc.Load(path);
            XmlElement root = doc.DocumentElement;
            var game = new Game();
            game.SavedXmlVersion = new System.Version(root.GetAttribute("Version"));
            game.SavedXmlVersionIndex = 0;
            game.SavedXmlEditorVersion = new System.Version(root.GetAttribute("EditorVersion"));
            game.FromXml(root);
            Tasks.SyncCursorsWithInteractionSchema(game.Cursors, InteractionSchema.Instance);
            return game;
        }

        private void RunTool(params string[] args)
        {
            var info = new ProcessStartInfo(_tool, string.Join(" ", args.Select(a => "\"" + a + "\"")))
            {
                UseShellExecute = false,
                CreateNoWindow = true,
                RedirectStandardOutput = true,
                RedirectStandardError = true,
            };
            using (Process process = Process.Start(info))
            {
                string output = process.StandardOutput.ReadToEnd() + process.StandardError.ReadToEnd();
                process.WaitForExit();
                Assert.That(process.ExitCode, Is.EqualTo(0), ToolFileName + " " + info.Arguments + ":" +
                            Environment.NewLine + output);
            }
        }

        // The texts as lines, whatever their line ends; the first differences on failure. The macros
        // of a run of #define lines may come in any order: the editor lists the views of a folder
        // before its subfolders, agfexport by ID (Tools/data/scriptgen.cpp), and the compiled
        // scripts do not depend on it
        private static void AssertSameLines(string fromTool, string fromEditor)
        {
            string[] tool = SortMacroRuns(SplitLines(fromTool));
            string[] editor = SortMacroRuns(SplitLines(fromEditor));
            var report = new StringBuilder();
            int shown = 0;
            for (int i = 0; i < Math.Max(tool.Length, editor.Length) && shown < 8; ++i)
            {
                string left = i < tool.Length ? tool[i] : "<end>";
                string right = i < editor.Length ? editor[i] : "<end>";
                if (left != right)
                {
                    report.AppendFormat("line {0}:{3}  agfexport: {1}{3}  editor:    {2}{3}", i + 1, left, right,
                        Environment.NewLine);
                    ++shown;
                }
            }
            Assert.That(report.ToString(), Is.Empty, "the headers differ (" + tool.Length + " and " + editor.Length +
                        " lines)");
        }

        private static string[] SortMacroRuns(string[] lines)
        {
            string[] sorted = (string[])lines.Clone();
            for (int start = 0; start < sorted.Length; )
            {
                int end = start;
                while (end < sorted.Length && sorted[end].StartsWith("#define ", StringComparison.Ordinal))
                {
                    ++end;
                }
                Array.Sort(sorted, start, end - start, StringComparer.Ordinal);
                start = end > start ? end : start + 1;
            }
            return sorted;
        }

        private static string[] SplitLines(string text)
        {
            text = text.Replace("\r\n", "\n");
            if (text.EndsWith("\n", StringComparison.Ordinal))
            {
                text = text.Substring(0, text.Length - 1);
            }
            return text.Length == 0 ? new string[0] : text.Split('\n');
        }

        private static string DefaultToolsDir()
        {
            return Path.GetFullPath(Path.Combine(TestContext.CurrentContext.TestDirectory, @"..\..\..\.build\x86\Release"));
        }

        private static string FindTool()
        {
            foreach (string dir in new[] { DefaultToolsDir(), Environment.GetEnvironmentVariable(ToolsVariable) })
            {
                if (!string.IsNullOrEmpty(dir) && File.Exists(Path.Combine(dir, ToolFileName)))
                {
                    return Path.GetFullPath(Path.Combine(dir, ToolFileName));
                }
            }
            return null;
        }

        // The project's Game.agf, or null
        private static string FindProject()
        {
            string path = Environment.GetEnvironmentVariable(ProjectVariable);
            if (string.IsNullOrEmpty(path))
            {
                return null;
            }
            if (Directory.Exists(path))
            {
                path = Path.Combine(path, "Game.agf");
            }
            if (!File.Exists(path))
            {
                Assert.Fail(ProjectVariable + " names no game project: " + path);
            }
            return Path.GetFullPath(path);
        }
    }
}
